import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

type Project = {
  id: string;
  name: string;
  status: ProjectStatus;
  used: number;
  quota: number;
};

const STATUSES: Array<{
  value: ProjectStatus;
  label: string;
  tone: 'success' | 'warning' | 'danger';
}> = [
  { value: 'active', label: 'Активен', tone: 'success' },
  { value: 'paused', label: 'Приостановлен', tone: 'warning' },
  { value: 'over', label: 'Превышение квоты', tone: 'danger' },
];

const PROJECTS: Project[] = [
  { id: 'p-1', name: 'Витрина заказов', status: 'active', used: 412, quota: 1000 },
  { id: 'p-2', name: 'Аналитика продаж и прогнозирование спроса', status: 'active', used: 780, quota: 1000 },
  { id: 'p-3', name: 'Мобильный клиент', status: 'paused', used: 120, quota: 800 },
  { id: 'p-4', name: 'Биллинг', status: 'over', used: 940, quota: 900 },
  { id: 'p-5', name: 'Поиск', status: 'active', used: 310, quota: 600 },
  { id: 'p-6', name: 'Импорт справочников', status: 'paused', used: 64, quota: 400 },
  { id: 'p-7', name: 'Уведомления', status: 'active', used: 288, quota: 500 },
  { id: 'p-8', name: 'Медиахранилище', status: 'over', used: 1180, quota: 1000 },
  { id: 'p-9', name: 'Личный кабинет', status: 'active', used: 150, quota: 700 },
  { id: 'p-10', name: 'Отчёты для бухгалтерии', status: 'paused', used: 210, quota: 450 },
  { id: 'p-11', name: 'Шлюз оплат', status: 'active', used: 505, quota: 1200 },
  { id: 'p-12', name: 'Внутренний портал документации команды разработки', status: 'active', used: 96, quota: 300 },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [filters, setFilters] = useState<ProjectStatus[]>(['active', 'over']);
  const [page, setPage] = useState(1);

  const visible = useMemo(
    () => (filters.length === 0 ? PROJECTS : PROJECTS.filter((p) => filters.includes(p.status))),
    [filters],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const rows = visible.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const removeFilter = (status: ProjectStatus) => {
    setFilters((prev) => prev.filter((value) => value !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setFilters([]);
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)', fontSize: '18px' }}>
          Расход по проектам
        </h2>
        <p style={{ margin: 0, fontSize: '13px', color: 'var(--jx-text-2)' }}>
          Заполненность квоты за текущий месяц. Найдено проектов: {visible.length}.
        </p>
      </header>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignItems: 'center' }}>
        {STATUSES.map((status) => {
          const active = filters.includes(status.value);
          return (
            <JxChip
              key={status.value}
              active={active}
              removable={active}
              onRemove={() => removeFilter(status.value)}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              onClick={() => {
                setFilters((prev) =>
                  prev.includes(status.value)
                    ? prev.filter((value) => value !== status.value)
                    : [...prev, status.value],
                );
                setPage(1);
              }}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  setFilters((prev) =>
                    prev.includes(status.value)
                      ? prev.filter((value) => value !== status.value)
                      : [...prev, status.value],
                  );
                  setPage(1);
                }
              }}
            >
              {status.label}
            </JxChip>
          );
        })}
        {filters.length > 0 && (
          <JxButton variant="ghost" size="sm" onClick={resetFilters}>
            Сбросить
          </JxButton>
        )}
      </div>

      {rows.length === 0 ? (
        <JxEmptyState
          title="Под фильтры ничего не подошло"
          message="Снимите выбранные статусы, чтобы увидеть все проекты и их расход квоты."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: '8px',
            }}
          >
            {rows.map((project) => {
              const status = STATUSES.find((item) => item.value === project.status)!;
              const percent = Math.round((project.used / project.quota) * 100);
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 16px',
                    background: 'var(--jx-surface-2)',
                    border: '1px solid var(--jx-border-2)',
                    borderRadius: 'var(--jx-r)',
                  }}
                >
                  <div style={{ flex: '1 1 auto', minWidth: 0 }}>
                    <div
                      style={{
                        fontSize: '14px',
                        fontWeight: 600,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}
                      title={project.name}
                    >
                      {project.name}
                    </div>
                    <div
                      style={{
                        fontSize: '12px',
                        color: 'var(--jx-text-2)',
                        fontFamily: 'var(--jx-font-mono)',
                      }}
                    >
                      {project.used} / {project.quota} ГБ
                    </div>
                  </div>

                  <JxProgressCircle
                    value={Math.min(percent, 100)}
                    showValue
                    role="img"
                    aria-label={`Квота заполнена на ${percent}%`}
                  />

                  <JxBadge tone={status.tone} dot>
                    {status.label}
                  </JxBadge>
                </li>
              );
            })}
          </ul>

          {pageCount > 1 && (
            <JxPagination
              total={pageCount}
              page={currentPage}
              onPageChange={setPage}
              aria-label="Страницы списка проектов"
            />
          )}
        </>
      )}
    </section>
  );
}

